/*
	VIOC_specops_request.sqf - agregado por tools/vio_build.py (parche specops_player; copia configurada, no es del autor
	de la mision). Fuente: work/v6_build/specops_player/.

	Cliente de "PEDIR: Operacion especial (IA)": CUALQUIER jugador (no solo el comandante) pide a la IA una de las
	operaciones especiales de VIOC_specops.sqf (paracaidistas, insercion en helicoptero o, de noche, incursion a pie),
	pagada con SUS fondos.
	  - La accion abre el mapa con un panel a la derecha: tipo (Cualquiera / Paracaidistas / Helicoptero / A pie de noche),
	    soldados (4 / 6 / 8) y "Unirse a mi grupo" (si cabe, el equipo se une a tu grupo al llegar; si no, ataca solo).
	  - Clic en el mapa = objetivo: un pueblo enemigo o neutral (atacar), uno tuyo (defender) o, lejos de los pueblos, un
	    punto (aseguran la zona; util para pedir refuerzos que se unan a ti). Shift+clic marca tambien "unirse".
	  - El panel muestra el objetivo, el costo, tus fondos, tu grupo y el enfriamiento; "CONFIRMAR" manda el pedido al
	    servidor (VIOC_fnc_soPlayerRequest), que valida todo otra vez y cobra; la respuesta llega en un aviso.
	  - Esc / M / CANCELAR cierra sin pedir nada.
	Solo cliente (hasInterface). Parametros VIOC_SPECOPS_PLAYER y VIOC_SPECOPS_PLAYER_COOLDOWN.
	Consola (Ejecucion local): [] spawn VIOC_SOR_fnc_open;   abre el panel;   VIOC_SO_PREQ_CFG / VIOC_SO_PREQ_AVAIL   datos del servidor
*/
if (!hasInterface) exitWith {};
if ((missionNamespace getVariable ["VIOC_SPECOPS_PLAYER", 1]) <= 0) exitWith {};

VIOC_SOR_TYPES = [["any", "Cualquiera"], ["para", "Paracaidistas"], ["heli", "Helicoptero"], ["raid", "A pie (noche)"]];
VIOC_SOR_SIZES = [4, 6, 8];
VIOC_SOR_SEL = [0, 1, false];	//--- [tipo, soldados, unirse]: se recuerda entre pedidos
VIOC_SOR_POS = [];
VIOC_SOR_CD_UNTIL = -1;			//--- time local hasta el que dura tu enfriamiento (lo dice el servidor)
VIOC_SOR_OPEN = false;
VIOC_SOR_CTRLS = [];
VIOC_SOR_C = [];				//--- [botones tipo, botones soldados, boton unirse, texto info]
VIOC_SOR_MK = "vioc_sor_target";

//--- La accion se ve si tu bando tiene operaciones especiales (lo publica el servidor).
VIOC_SOR_fnc_avail = {
	private _i = [west, east] find CTI_P_SideJoined;
	_i >= 0 && {((missionNamespace getVariable ["VIOC_SO_PREQ_AVAIL", []]) param [_i, false]) isEqualTo true}
};

//--- Texto seguro para parseText.
VIOC_SOR_fnc_esc = {
	params [["_s", "", [""]]];
	private _o = [];
	{
		switch (_x) do {
			case 38: {_o append (toArray "&amp;")};
			case 60: {_o append (toArray "&lt;")};
			case 62: {_o append (toArray "&gt;")};
			default {_o pushBack _x};
		};
	} forEach (toArray _s);
	toString _o
};

//--- Precio estimado (mismo calculo que el servidor: soldados + 3 avion / + 2 helicoptero, x soldado de nivel 2, x multiplicador).
VIOC_SOR_fnc_price = {
	params ["_type", "_n"];
	private _cfg = missionNamespace getVariable ["VIOC_SO_PREQ_CFG", []];
	private _u = _cfg param [0, 900];
	private _m = _cfg param [1, 1];
	if !(_u isEqualType 0) then {_u = 900};
	if !(_m isEqualType 0) then {_m = 1};
	private _extra = switch (_type) do {case "heli": {2}; case "raid": {0}; default {3}};
	round ((round (_u * (_n + _extra))) * _m)
};

//--- Objetivo previsto para una posicion: [pueblo u objNull, texto del modo, problema o ""].
VIOC_SOR_fnc_target = {
	params ["_pos"];
	if (count _pos < 2) exitWith {[objNull, "", "Haz clic en el mapa para elegir el objetivo."]};
	private _cfg = missionNamespace getVariable ["VIOC_SO_PREQ_CFG", []];
	private _tr = _cfg param [3, 700];
	private _br = _cfg param [4, 500];
	if ((_pos select 0) < 0 || {(_pos select 1) < 0} || {(_pos select 0) > worldSize} || {(_pos select 1) > worldSize}) exitWith {[objNull, "", "El objetivo esta fuera del mapa."]};
	private _own = [];
	private _hq = CTI_P_SideJoined call CTI_CO_FNC_GetSideHQ;
	if (!isNil "_hq" && {_hq isEqualType objNull} && {!isNull _hq}) then {_own pushBack _hq};
	private _sts = CTI_P_SideJoined call CTI_CO_FNC_GetSideStructures;
	if (!isNil "_sts" && {_sts isEqualType []}) then {_own append (_sts select {_x isEqualType objNull && {!isNull _x}})};
	if (({(_x distance2D _pos) < _br} count _own) > 0) exitWith {[objNull, "", "Eso es tu base: elige un pueblo o un punto fuera de ella."]};
	private _town = objNull;
	private _bd = _tr;
	{
		private _d = _x distance2D _pos;
		if (_d < _bd) then {_bd = _d; _town = _x};
	} forEach (missionNamespace getVariable ["CTI_Towns", []]);
	if (isNull _town) exitWith {
		if (surfaceIsWater _pos) exitWith {[objNull, "", "Haz clic en tierra o cerca de un pueblo."]};
		[objNull, format ["asegurar la zona (cuadricula %1)", mapGridPosition _pos], ""]
	};
	private _name = [_town getVariable ["cti_town_name", "pueblo"]] call VIOC_SOR_fnc_esc;
	if ((_town getVariable ["cti_town_sideID", -1]) == (CTI_P_SideJoined call CTI_CO_FNC_GetSideID)) exitWith {[_town, format ["defender %1 (tuyo)", _name], ""]};
	[_town, format ["atacar %1", _name], ""]
};

//--- Rehace los textos del panel (seleccion, objetivo, costo, fondos, grupo, enfriamiento).
VIOC_SOR_fnc_refresh = {
	if (count VIOC_SOR_C < 4) exitWith {};
	VIOC_SOR_C params ["_tb", "_sb", "_jb", "_info"];
	VIOC_SOR_SEL params ["_ti", "_si", "_join"];
	private _night = sunOrMoon < 0.5;
	if (_ti == 3 && {!_night}) then {VIOC_SOR_SEL set [0, 0]; _ti = 0};	//--- de dia no hay incursion a pie
	{
		private _sel = _forEachIndex == _ti;
		private _lbl = (VIOC_SOR_TYPES select _forEachIndex) select 1;
		_x ctrlSetText (if (_sel) then {format ["> %1 <", _lbl]} else {_lbl});
		_x ctrlSetBackgroundColor (if (_sel) then {[0.25, 0.55, 0.2, 1]} else {[0.2, 0.2, 0.2, 0.9]});
		if (_forEachIndex == 3) then {_x ctrlEnable _night};
	} forEach _tb;
	{
		private _sel = _forEachIndex == _si;
		_x ctrlSetText (if (_sel) then {format ["> %1 <", VIOC_SOR_SIZES select _forEachIndex]} else {str (VIOC_SOR_SIZES select _forEachIndex)});
		_x ctrlSetBackgroundColor (if (_sel) then {[0.25, 0.55, 0.2, 1]} else {[0.2, 0.2, 0.2, 0.9]});
	} forEach _sb;
	_jb ctrlSetText (if (_join) then {"Unirse a mi grupo: SI"} else {"Unirse a mi grupo: NO (atacan solos)"});
	_jb ctrlSetBackgroundColor (if (_join) then {[0.25, 0.55, 0.2, 1]} else {[0.2, 0.2, 0.2, 0.9]});
	private _type = (VIOC_SOR_TYPES select _ti) select 0;
	private _n = VIOC_SOR_SIZES select _si;
	([VIOC_SOR_POS] call VIOC_SOR_fnc_target) params ["", "_what", "_prob"];
	private _price = [_type, _n] call VIOC_SOR_fnc_price;
	private _ptxt = if (_type == "any") then {format ["hasta $%1 (depende del tipo que elija el mando)", _price]} else {format ["$%1", _price]};
	private _funds = call CTI_CL_FNC_GetPlayerFunds;
	if (isNil "_funds" || {!(_funds isEqualType 0)}) then {_funds = 0};
	private _cap = missionNamespace getVariable ["CTI_AI_PLAYER_TEAMS_GROUPSIZE", 12];
	private _g = count units group player;
	private _cd = (VIOC_SOR_CD_UNTIL - time) max 0;
	private _l = [];
	_l pushBack format ["<t color='#9fd3ff'>Objetivo:</t> %1", if (_prob != "") then {format ["<t color='#F56363'>%1</t>", _prob]} else {_what}];
	_l pushBack format ["<t color='#9fd3ff'>Costo:</t> %1", _ptxt];
	_l pushBack format ["<t color='#9fd3ff'>Tus fondos:</t> <t color='%2'>$%1</t>", round _funds, if (_funds >= _price) then {"#76F563"} else {"#F56363"}];
	if (_join) then {
		_l pushBack format ["<t color='#9fd3ff'>Tu grupo:</t> %1/%2%3", _g, _cap, if ((_g + _n) > _cap) then {format [" <t color='#F5D363'>(no caben %1 mas: atacaran solos)</t>", _n]} else {""}];
	};
	if (_cd > 0) then {_l pushBack format ["<t color='#F5D363'>Enfriamiento: faltan %1 s</t>", round _cd]};
	if (_type == "raid") then {_l pushBack "<t color='#aaaaaa'>A pie: salen de un pueblo tuyo a menos de 2,5 km del objetivo.</t>"};
	_info ctrlSetStructuredText parseText format ["<t size='0.85'>%1</t>", _l joinString "<br/>"];
};

//--- Clic en el mapa (evento MapSingleClick mientras el panel esta abierto).
VIOC_SOR_fnc_click = {
	params ["_pos", ["_shift", false]];
	VIOC_SOR_POS = [_pos select 0, _pos select 1, 0];
	if (_shift) then {VIOC_SOR_SEL set [2, true]};
	deleteMarkerLocal VIOC_SOR_MK;
	private _m = createMarkerLocal [VIOC_SOR_MK, VIOC_SOR_POS];
	_m setMarkerTypeLocal "mil_objective";
	_m setMarkerColorLocal "ColorOrange";
	_m setMarkerTextLocal "Objetivo de la operacion";
	call VIOC_SOR_fnc_refresh;
};

VIOC_SOR_fnc_setType = {params ["_i"]; VIOC_SOR_SEL set [0, _i]; call VIOC_SOR_fnc_refresh};
VIOC_SOR_fnc_setSize = {params ["_i"]; VIOC_SOR_SEL set [1, _i]; call VIOC_SOR_fnc_refresh};
VIOC_SOR_fnc_toggleJoin = {VIOC_SOR_SEL set [2, !(VIOC_SOR_SEL select 2)]; call VIOC_SOR_fnc_refresh};

//--- CONFIRMAR: manda el pedido al servidor (que vuelve a validar todo y cobra).
VIOC_SOR_fnc_confirm = {
	([VIOC_SOR_POS] call VIOC_SOR_fnc_target) params ["", "", "_prob"];
	if (_prob != "") exitWith {hint parseText format ["<t color='#F56363'>%1</t>", _prob]};
	if (VIOC_SOR_CD_UNTIL > time) exitWith {hint format ["Todavia no puedes pedir otra operacion: faltan %1 s.", round (VIOC_SOR_CD_UNTIL - time)]};
	VIOC_SOR_SEL params ["_ti", "_si", "_join"];
	private _type = (VIOC_SOR_TYPES select _ti) select 0;
	private _n = VIOC_SOR_SIZES select _si;
	private _seen = [_type, _n] call VIOC_SOR_fnc_price;
	private _cap = missionNamespace getVariable ["CTI_AI_PLAYER_TEAMS_GROUPSIZE", 12];
	if !(_cap isEqualType 0) then {_cap = 12};
	[player, _type, VIOC_SOR_POS, _join, _n, _seen, _cap] remoteExecCall ["VIOC_fnc_soPlayerRequest", 2];
	systemChat "[Operacion especial] Pedido enviado al mando...";
	VIOC_SOR_OPEN = false;
	openMap false;
};

//--- Crea el panel sobre el mapa (pantalla 12). Devuelve true si pudo.
VIOC_SOR_fnc_build = {
	params ["_d"];
	VIOC_SOR_CTRLS = [];
	private _mk = {
		params ["_cls", "_pos"];
		private _c = _d ctrlCreate [_cls, -1];
		_c ctrlSetPosition _pos;
		_c ctrlCommit 0;
		VIOC_SOR_CTRLS pushBack _c;
		_c
	};
	private _W = safeZoneW;
	private _H = safeZoneH;
	private _x0 = safeZoneX + _W * 0.735;
	private _y0 = safeZoneY + _H * 0.09;
	private _w = _W * 0.255;
	private _p = _W * 0.006;
	private _lh = _H * 0.034;
	private _iw = _w - 2 * _p;
	private _bg = ["RscText", [_x0, _y0, _w, _H * 0.60]] call _mk;
	if (isNull _bg) exitWith {false};
	_bg ctrlSetBackgroundColor [0, 0, 0, 0.8];
	private _y = _y0 + _p;
	private _t = ["RscStructuredText", [_x0 + _p, _y, _iw, _lh * 2.6]] call _mk;
	_t ctrlSetStructuredText parseText "<t size='1.05' color='#eac6ff'>PEDIR OPERACION ESPECIAL</t><br/><t size='0.8'>Clic en el mapa: pueblo enemigo (atacar), tuyo (defender) o un punto lejos de los pueblos. Se paga con TUS fondos.</t>";
	_y = _y + _lh * 2.7;
	private _l1 = ["RscText", [_x0 + _p, _y, _iw, _lh]] call _mk;
	_l1 ctrlSetText "Tipo:";
	_y = _y + _lh;
	private _tb = [];
	private _bw = (_iw - _p) / 2;
	{
		private _b = ["RscButton", [_x0 + _p + (_forEachIndex mod 2) * (_bw + _p), _y + (floor (_forEachIndex / 2)) * (_lh + _p * 0.6), _bw, _lh]] call _mk;
		_b ctrlAddEventHandler ["ButtonClick", format ["with missionNamespace do {[%1] call VIOC_SOR_fnc_setType}", _forEachIndex]];
		_tb pushBack _b;
	} forEach VIOC_SOR_TYPES;
	(_tb select 3) ctrlSetTooltip "Solo de noche: el equipo sale a pie de un pueblo tuyo cercano";
	_y = _y + 2 * (_lh + _p * 0.6) + _p * 0.4;
	private _l2 = ["RscText", [_x0 + _p, _y, _iw, _lh]] call _mk;
	_l2 ctrlSetText "Soldados:";
	_y = _y + _lh;
	private _sb = [];
	private _sw = (_iw - 2 * _p) / 3;
	{
		private _b = ["RscButton", [_x0 + _p + _forEachIndex * (_sw + _p), _y, _sw, _lh]] call _mk;
		_b ctrlAddEventHandler ["ButtonClick", format ["with missionNamespace do {[%1] call VIOC_SOR_fnc_setSize}", _forEachIndex]];
		_sb pushBack _b;
	} forEach VIOC_SOR_SIZES;
	_y = _y + _lh + _p * 1.2;
	private _jb = ["RscButton", [_x0 + _p, _y, _iw, _lh]] call _mk;
	_jb ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {call VIOC_SOR_fnc_toggleJoin}"];
	_jb ctrlSetTooltip "Al llegar se unen a tu grupo si caben (Shift+clic en el mapa tambien lo activa); si no, atacan solos";
	_y = _y + _lh + _p * 1.2;
	private _info = ["RscStructuredText", [_x0 + _p, _y, _iw, _H * 0.17]] call _mk;
	_y = _y + _H * 0.17 + _p;
	private _ok = ["RscButton", [_x0 + _p, _y, _bw, _lh * 1.2]] call _mk;
	_ok ctrlSetText "CONFIRMAR";
	_ok ctrlSetBackgroundColor [0.2, 0.45, 0.75, 1];
	_ok ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {call VIOC_SOR_fnc_confirm}"];
	private _ko = ["RscButton", [_x0 + _p * 2 + _bw, _y, _bw, _lh * 1.2]] call _mk;
	_ko ctrlSetText "CANCELAR";
	_ko ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {VIOC_SOR_OPEN = false; openMap false}"];
	VIOC_SOR_C = [_tb, _sb, _jb, _info];
	true
};

//--- Cierra el panel: borra controles, marcador y evento del mapa.
VIOC_SOR_fnc_close = {
	if (!isNil "VIOC_SOR_EH") then {removeMissionEventHandler ["MapSingleClick", VIOC_SOR_EH]; VIOC_SOR_EH = nil};
	{if (!isNull _x) then {ctrlDelete _x}} forEach VIOC_SOR_CTRLS;
	VIOC_SOR_CTRLS = [];
	VIOC_SOR_C = [];
	deleteMarkerLocal VIOC_SOR_MK;
	VIOC_SOR_OPEN = false;
};

//--- Accion "PEDIR: Operacion especial (IA)" (se corre con spawn).
VIOC_SOR_fnc_open = {
	if (VIOC_SOR_OPEN) exitWith {};
	if !(call VIOC_SOR_fnc_avail) exitWith {hint "Tu bando no tiene operaciones especiales en este escenario."};
	if (!alive player) exitWith {};
	VIOC_SOR_OPEN = true;
	VIOC_SOR_POS = [];
	openMap [true, false];
	private _t = diag_tickTime + 3;
	waitUntil {sleep 0.05; visibleMap || {diag_tickTime > _t}};
	private _d = findDisplay 12;
	if (!visibleMap || {isNull _d} || {!([_d] call VIOC_SOR_fnc_build)}) exitWith {
		call VIOC_SOR_fnc_close;
		hint "No se pudo abrir el panel del mapa. Prueba otra vez con el mapa cerrado.";
	};
	VIOC_SOR_EH = addMissionEventHandler ["MapSingleClick", {
		params ["", "_pos", "", "_shift"];
		[_pos, _shift] call VIOC_SOR_fnc_click;
	}];
	call VIOC_SOR_fnc_refresh;
	private _next = diag_tickTime + 1;
	waitUntil {
		sleep 0.1;
		if (diag_tickTime > _next) then {_next = diag_tickTime + 1; call VIOC_SOR_fnc_refresh};
		!visibleMap || {!alive player} || {!VIOC_SOR_OPEN}
	};
	call VIOC_SOR_fnc_close;
	if (visibleMap) then {openMap false};
};

//--- Respuesta del servidor (VIOC_fnc_soPreqReply).
VIOC_SOR_fnc_reply = {
	params ["_ok", "_text", ["_cd", -1]];
	if (_cd isEqualType 0 && {_cd >= 0}) then {VIOC_SOR_CD_UNTIL = time + _cd};
	private _txt = [_text] call VIOC_SOR_fnc_esc;
	hint parseText format ["<t size='1.1' color='%1'>%2</t><br/><br/><t align='left'>%3</t>", if (_ok) then {"#76F563"} else {"#F56363"}, if (_ok) then {"Operacion especial"} else {"Operacion especial: no se pudo"}, _txt];
	systemChat format ["[Operacion especial] %1", _text];
};

//--- El equipo se unio a tu grupo: cuando ya son locales aqui, van hacia el objetivo (y esperan tus ordenes).
VIOC_SOR_fnc_joined = {
	params ["_units", "_dest"];
	[_units, _dest] spawn {
		params ["_units", "_dest"];
		sleep 2;
		{
			if (alive _x && {local _x} && {(group _x) == (group player)}) then {_x doMove (_dest getPos [random 40, random 360])};
		} forEach _units;
	};
};

//--- VIOC specops_player: los pedidos de los jugadores (VIOC_SPECOPS_PLAYER) funcionan aunque las operaciones automaticas
//--- de la IA esten apagadas (VIOC_SPECOPS = 0); en ese caso el gestor no lanza ninguna de la IA (VIOC_fnc_soSideEnabled).
VIOC_SO_PREQ_MODE = missionNamespace getVariable ["VIOC_SPECOPS_PLAYER", 1];
if !(VIOC_SO_PREQ_MODE isEqualType 0) then {VIOC_SO_PREQ_MODE = 1};
if (VIOC_SO_MODE <= 0 && {VIOC_SO_PREQ_MODE <= 0}) exitWith {diag_log "VIOC_specops: desactivado (VIOC_SPECOPS = 0 y VIOC_SPECOPS_PLAYER = 0)."};

//--- VIOC specops_player: si el jugador pidio "unirse a mi grupo" y caben, el equipo se une a su grupo y la operacion termina aqui
	if (_op getOrDefault ["join", false]) then {[_op, _team, _town] call VIOC_fnc_soPreqJoin};
	if (_op getOrDefault ["joined", false]) exitWith {
		format ["%1: fin (unidos al grupo del jugador)", _pkg get "id"] call VIOC_fnc_soLog;
		[_i, _op get "tok"] call VIOC_fnc_soRelease;
	};

steps.anchor:
private _coast = [getPosATL _town] call VIOC_fnc_soNearCoast;
	//--- opciones [paquete, tipo, peso, principal]
	private _opts = [];
	{
		_x params ["_p", "_w", "_main"];
		if (!(_p getOrDefault ["coast", false]) || {_coast}) then {
			{
				private _ty = _x;
				private _ok = switch (_ty) do {
					case "para": {(count (_p get "vplanes") + count (_p get "vhelis")) > 0 && {(_p get "vchute") != ""}};
					case "heli": {count (_p get "vhelis") > 0};
					case "raid": {_night && {_mode == "attack"}};
					default {false};
				};
				if (_ok && {_want in ["", "any", _ty]}) then {
					_opts pushBack [_p, _ty, _w * (if (_ty == "raid") then {1.3} else {1}), _main];
				};
			} forEach (_p get "types");
		};
	} forEach _pkgs;
	if (count _opts == 0) exitWith {"sin opciones (tipo pedido o de dia)"};
	//--- elige y busca el lugar (zona de salto, de aterrizaje o salida a pie); hasta 4 intentos
	private _chosen = [];
	private _pos = [];
	for "_k" from 1 to 4 do {
		if (count _opts == 0) exitWith {};
		private _idx = [_opts apply {_x select 2}] call VIOC_fnc_soPickIdx;
		private _o = _opts select _idx;
		_pos = switch (_o select 1) do {
			case "para": {[_town, _from, _side, _mode] call VIOC_fnc_soFindDZ};
			case "heli": {[_town, _from, _side, _mode] call VIOC_fnc_soFindLZ};
			default {[_town, _side, selectRandom ((_o select 0) get "vunits")] call VIOC_fnc_soFindRaidStart};
		};
		if (count _pos > 0) exitWith {_chosen = _o};
		_opts deleteAt _idx;
	};
	if (count _chosen == 0) exitWith {format ["sin lugar de salto/aterrizaje/salida cerca de %1", _town getVariable ["cti_town_name", "?"]]};
	_chosen params ["_pkg", "_type", "", "_main"];
	private _air = "";
	if (_type == "para") then {
		_air = if (count (_pkg get "vplanes") > 0) then {selectRandom (_pkg get "vplanes")} else {selectRandom (_pkg get "vhelis")};
	};
	if (_type == "heli") then {_air = selectRandom (_pkg get "vhelis")};

steps.text:
//--- VIOC specops_player: la eleccion de paquete, tipo y lugar paso a VIOC_fnc_soPlan (mismo codigo; la usan tambien los pedidos de jugadores)
	private _plan = [_side, _town, _mode, _from, _want, _pkgs] call VIOC_fnc_soPlan;
	if (_plan isEqualType "") exitWith {_plan};
	_plan params ["_pkg", "_type", "_main", "_pos", "_air"];

//--- VIOC specops_player: eleccion de paquete, tipo y lugar hacia un objetivo (antes estaba dentro de VIOC_fnc_soTryLaunch;
//--- el codigo es el mismo). La usan la IA y los pedidos de jugadores. Devuelve [paquete, tipo, principal, lugar, aparato]
//--- o el motivo por el que no se puede (texto).
VIOC_fnc_soPlan = {
	params ["_side", "_town", "_mode", "_from", ["_want", ""], ["_pkgs", []]];
	if (count _pkgs == 0) then {_pkgs = [_side] call VIOC_fnc_soSidePackages};
	if (count _pkgs == 0) exitWith {"sin unidades especiales para esta nacion/epoca"};
	private _night = sunOrMoon < 0.5;
	private _coast = [getPosATL _town] call VIOC_fnc_soNearCoast;
	//--- opciones [paquete, tipo, peso, principal]
	private _opts = [];
	{
		_x params ["_p", "_w", "_main"];
		if (!(_p getOrDefault ["coast", false]) || {_coast}) then {
			{
				private _ty = _x;
				private _ok = switch (_ty) do {
					case "para": {(count (_p get "vplanes") + count (_p get "vhelis")) > 0 && {(_p get "vchute") != ""}};
					case "heli": {count (_p get "vhelis") > 0};
					case "raid": {_night && {_mode == "attack"}};
					default {false};
				};
				if (_ok && {_want in ["", "any", _ty]}) then {
					_opts pushBack [_p, _ty, _w * (if (_ty == "raid") then {1.3} else {1}), _main];
				};
			} forEach (_p get "types");
		};
	} forEach _pkgs;
	if (count _opts == 0) exitWith {"sin opciones (tipo pedido o de dia)"};
	//--- elige y busca el lugar (zona de salto, de aterrizaje o salida a pie); hasta 4 intentos
	private _chosen = [];
	private _pos = [];
	for "_k" from 1 to 4 do {
		if (count _opts == 0) exitWith {};
		private _idx = [_opts apply {_x select 2}] call VIOC_fnc_soPickIdx;
		private _o = _opts select _idx;
		_pos = switch (_o select 1) do {
			case "para": {[_town, _from, _side, _mode] call VIOC_fnc_soFindDZ};
			case "heli": {[_town, _from, _side, _mode] call VIOC_fnc_soFindLZ};
			default {[_town, _side, selectRandom ((_o select 0) get "vunits")] call VIOC_fnc_soFindRaidStart};
		};
		if (count _pos > 0) exitWith {_chosen = _o};
		_opts deleteAt _idx;
	};
	if (count _chosen == 0) exitWith {format ["sin lugar de salto/aterrizaje/salida cerca de %1", _town getVariable ["cti_town_name", "?"]]};
	_chosen params ["_pkg", "_type", "", "_main"];
	private _air = "";
	if (_type == "para") then {
		_air = if (count (_pkg get "vplanes") > 0) then {selectRandom (_pkg get "vplanes")} else {selectRandom (_pkg get "vhelis")};
	};
	if (_type == "heli") then {_air = selectRandom (_pkg get "vhelis")};
	[_pkg, _type, _main, _pos, _air]
};

//=====================================================================================================================
//--- VIOC specops_player: operaciones especiales PEDIDAS POR UN JUGADOR (cualquiera del bando, no solo el comandante).
//--- El cliente (VIOC_specops_request.sqf, accion "PEDIR: Operacion especial (IA)") manda con remoteExecCall
//--- [jugador, tipo, posicion del clic, unirse a su grupo, soldados, precio que vio, tope de su grupo] a
//--- VIOC_fnc_soPlayerRequest, que corre aqui (servidor) y vuelve a validar TODO antes de cobrar: parametro de lobby,
//--- jugador vivo y de oeste/este, 1 pedido activo por jugador, enfriamiento por jugador (VIOC_SPECOPS_PLAYER_COOLDOWN),
//--- objetivo dentro del mapa, fuera de tu base y lejos de la enemiga, pueblo a menos de 700 m del clic (propio =
//--- defender, otro = atacar; si no hay, el punto mismo), tope de soldados pedidos por bando, presupuesto de IA de otro
//--- parche (VIOC_PERF_AI_MAX / VIOC_PERF_AI_COUNT), lugar de salto/aterrizaje/salida (VIOC_fnc_soPlan) y por ultimo
//--- los fondos del jugador (CTI_CO_FNC_GetFunds / CTI_CO_FNC_ChangeFunds, los del menu de compra; si es el comandante,
//--- los del comandante), sin interrupciones entre mirar y descontar.
//--- Un pedido NO ocupa la ranura de la operacion automatica del bando (VIOC_SO_ACTIVE: su token es un texto que
//--- VIOC_fnc_soRelease reconoce) y sus soldados (vioc_so_preq) no cuentan para el tope de la IA (VIOC_SO_MAXUNITS):
//--- nunca bloquea las operaciones de la IA. Mismos avisos que las de la IA, con "(pedida por <nombre>)".
//--- Consola (servidor; en partida alojada vale "Ejecucion local"):
//---     VIOC_SO_PREQ        pedidos activos [uid, token, inicio, ayudante]
//---     VIOC_SO_PREQ_CD     ultimos pedidos aceptados [uid, time]   (VIOC_SO_PREQ_CD = []; borra los enfriamientos)
//=====================================================================================================================
VIOC_SO_PREQ = [];
VIOC_SO_PREQ_CD = [];
VIOC_SO_PREQ_COOLDOWN = missionNamespace getVariable ["VIOC_SPECOPS_PLAYER_COOLDOWN", 10];
if !(VIOC_SO_PREQ_COOLDOWN isEqualType 0) then {VIOC_SO_PREQ_COOLDOWN = 10};
VIOC_SO_PREQ_COOLDOWN = ((VIOC_SO_PREQ_COOLDOWN max 0) min 120) * 60;
VIOC_SO_PREQ_MULT = [1, 1, 0.5] select ((VIOC_SO_PREQ_MODE max 0) min 2);	//--- 2 = a mitad de precio
VIOC_SO_PREQ_SIDECAP = 16;	//--- soldados pedidos por jugadores vivos por bando, con el equipo nuevo (sin los que se retiran ni los unidos a un grupo)
VIOC_SO_PREQ_TOWNR = 700;	//--- un pueblo a menos de esto del clic es el objetivo; si no hay ninguno, el objetivo es el punto
VIOC_SO_PREQ_BASER = 500;	//--- no se puede pedir a menos de esto de tu HQ o de tus estructuras
VIOC_SO_PREQ_ENEMYR = 800;	//--- ni a menos de esto de una base enemiga

//--- Presupuesto de IA de otro parche (VIOC_PERF_AI_MAX > 0): true si caben _n unidades mas.
VIOC_fnc_soPerfOk = {
	params [["_n", 0]];
	private _max = missionNamespace getVariable ["VIOC_PERF_AI_MAX", 0];
	if (!(_max isEqualType 0) || {_max <= 0}) exitWith {true};
	private _cnt = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", 0];
	if !(_cnt isEqualType 0) exitWith {true};
	(_cnt + _n) <= _max
};

//--- Identificador del jugador (UID; en "Un jugador" puede venir vacio).
VIOC_fnc_soPreqUID = {
	params ["_p"];
	private _u = getPlayerUID _p;
	if (_u == "") then {_u = "local"};
	_u
};

//--- "12:30" o "45 s"
VIOC_fnc_soPreqTime = {
	params ["_s"];
	_s = round _s;
	if (_s < 60) exitWith {format ["%1 s", _s]};
	private _sec = _s mod 60;
	format ["%1:%2%3 min", floor (_s / 60), ["", "0"] select (_sec < 10), _sec]
};

//--- Libera el pedido de un jugador (por su token) y borra su objeto ayudante (objetivo "punto").
VIOC_fnc_soPreqFree = {
	params ["_tok"];
	{
		if ((_x select 1) isEqualTo _tok) then {
			private _h = _x select 3;
			if (!isNull _h) then {deleteVehicle _h};
		};
	} forEach VIOC_SO_PREQ;
	VIOC_SO_PREQ = VIOC_SO_PREQ select {!((_x select 1) isEqualTo _tok)};
};

//--- true si el jugador tiene un pedido en curso (uno colgado se libera solo a la hora y media, como el vigilante).
VIOC_fnc_soPreqActive = {
	params ["_uid"];
	private _i = VIOC_SO_PREQ findIf {(_x select 0) == _uid};
	if (_i < 0) exitWith {false};
	private _e = VIOC_SO_PREQ select _i;
	if ((time - (_e select 2)) > (VIOC_SO_LIFETIME + 3000)) exitWith {[_e select 1] call VIOC_fnc_soPreqFree; false};
	true
};

//--- Segundos de enfriamiento que le quedan al jugador / anotar (o borrar con _t < 0) su ultimo pedido.
VIOC_fnc_soPreqCooldown = {
	params ["_uid"];
	private _i = VIOC_SO_PREQ_CD findIf {(_x select 0) == _uid};
	if (_i < 0) exitWith {0};
	((((VIOC_SO_PREQ_CD select _i) select 1) + VIOC_SO_PREQ_COOLDOWN) - time) max 0
};
VIOC_fnc_soPreqSetCD = {
	params ["_uid", "_t"];
	VIOC_SO_PREQ_CD = VIOC_SO_PREQ_CD select {(_x select 0) != _uid};
	if (_t >= 0) then {VIOC_SO_PREQ_CD pushBack [_uid, _t]};
};

//--- Cobro o devolucion (VIOC_fnc_soCharge con pagador ["player", grupo, uid, precio, bando]). La devolucion completa
//--- (operacion cancelada antes de llegar) borra tambien el enfriamiento.
VIOC_fnc_soPreqCharge = {
	params ["_payer", "_amount"];
	_payer params ["", ["_grp", grpNull], ["_uid", ""], ["_price", 0], ["_side", sideUnknown]];
	if (isNull _grp || {_amount == 0}) exitWith {};
	[_grp, _side, _amount] call CTI_CO_FNC_ChangeFunds;
	if (_amount > 0 && {_amount >= _price}) then {[_uid, -1] call VIOC_fnc_soPreqSetCD};
};

//--- Respuesta al jugador que pidio (aviso en pantalla y chat). _cd = segundos de enfriamiento que le quedan (o -1).
VIOC_fnc_soPreqReply = {
	params ["_player", "_ok", "_text", ["_cd", -1]];
	if (isNull _player) exitWith {};
	[_ok, _text, _cd] remoteExecCall ["VIOC_SOR_fnc_reply", _player];
};

//--- "Unirse a mi grupo" (lo llama VIOC_fnc_soRunOp cuando el equipo ya esta en tierra): si el jugador sigue vivo, es
//--- de este bando y caben (tope del grupo), el equipo se une a su grupo (joinSilent) y va hacia el objetivo.
VIOC_fnc_soPreqJoin = {
	params ["_op", "_team", "_town"];
	private _side = _op get "side";
	private _pname = (_op get "pkg") get "name";
	private _uid = _op getOrDefault ["preq", ""];
	private _req = _op getOrDefault ["req", objNull];
	if (isNull _req || {!alive _req}) then {
		private _c = (allPlayers - (entities "HeadlessClient_F")) select {alive _x && {([_x] call VIOC_fnc_soPreqUID) == _uid}};
		if (count _c == 0 && {!isMultiplayer} && {hasInterface} && {alive player}) then {_c = [player]};
		_req = if (count _c > 0) then {_c select 0} else {objNull};
	};
	private _alive = (units _team) select {alive _x};
	if (isNull _req || {!alive _req} || {(side group _req) != _side} || {count _alive == 0}) exitWith {
		[_side, format ["[Operacion especial] %1: quien la pidio no esta disponible; el equipo actua por su cuenta.", _pname]] call VIOC_fnc_soSay;
	};
	private _cap = _op getOrDefault ["cap", 12];
	private _n = count units group _req;
	if ((_n + count _alive) > _cap) exitWith {
		[_side, format ["[Operacion especial] %1: no caben en el grupo de %2 (%3 + %4 > %5); actuan por su cuenta.", _pname, name _req, _n, count _alive, _cap]] call VIOC_fnc_soSay;
		[_req, false, format ["Tu equipo no cabe en tu grupo (%1 + %2 > %3): actua por su cuenta contra el objetivo.", _n, count _alive, _cap], -1] call VIOC_fnc_soPreqReply;
	};
	_alive joinSilent (group _req);
	{_x setVariable ["vioc_so_joined", true, true]} forEach _alive;
	_op set ["joined", true];
	private _dest = getPosATL _town;
	[_alive, _dest] remoteExecCall ["VIOC_SOR_fnc_joined", _req];
	private _tname = _town getVariable ["cti_town_name", "el objetivo"];
	[_side, format ["[Operacion especial] %1 se unieron al grupo de %2.", _pname, name _req]] call VIOC_fnc_soSay;
	[_req, true, format ["Tu equipo (%1 soldados) se unio a tu grupo y va hacia %2. Ya son tuyos: dales ordenes como al resto de tu grupo.", count _alive, _tname], -1] call VIOC_fnc_soPreqReply;
	format ["%1: %2 soldados se unieron al grupo de %3", (_op get "pkg") get "id", count _alive, name _req] call VIOC_fnc_soLog;
};

//--- Pedido de un jugador (llega con remoteExecCall desde su cliente). Solo comprueba el remitente y responde.
VIOC_fnc_soPlayerRequest = {
	params [["_player", objNull, [objNull]], ["_want", "any", [""]], ["_pos", [], [[]]], ["_join", false, [false]], ["_size", 6, [0]], ["_seen", -1, [0]], ["_cap", 12, [0]]];
	if (!isServer || {isNull _player}) exitWith {};
	private _ro = remoteExecutedOwner;
	if (isMultiplayer && {_ro > 0} && {_ro != (owner _player)}) exitWith {format ["pedido ignorado: la maquina %1 no controla a %2", _ro, name _player] call VIOC_fnc_soLog};
	private _r = [_player, _want, _pos, _join, _size, _seen, _cap] call VIOC_fnc_soPreqDo;
	if (_r != "ok") then {
		[_player, false, _r, [[_player] call VIOC_fnc_soPreqUID] call VIOC_fnc_soPreqCooldown] call VIOC_fnc_soPreqReply;
		format ["pedido de %1 rechazado: %2", name _player, _r] call VIOC_fnc_soLog;
	};
};

//--- Valida, cobra y lanza. Devuelve "ok" o el motivo (texto para el jugador).
VIOC_fnc_soPreqDo = {
	params ["_player", "_want", "_pos", "_join", "_size", "_seen", "_cap"];
	if (VIOC_SO_PREQ_MODE <= 0) exitWith {"las operaciones a pedido estan desactivadas en el lobby"};
	if (missionNamespace getVariable ["CTI_GameOver", false]) exitWith {"la partida termino"};
	if (!alive _player) exitWith {"tienes que estar vivo"};
	private _side = side group _player;
	if !(_side in [west, east]) exitWith {"tu bando no puede pedir operaciones especiales"};
	private _uid = [_player] call VIOC_fnc_soPreqUID;
	if ([_uid] call VIOC_fnc_soPreqActive) exitWith {"ya tienes una operacion pedida en curso (una por jugador)"};
	private _cd = [_uid] call VIOC_fnc_soPreqCooldown;
	if (_cd > 0) exitWith {format ["todavia no: podras pedir otra en %1", [_cd] call VIOC_fnc_soPreqTime]};
	if !(_want in ["any", "para", "heli", "raid"]) then {_want = "any"};
	_size = ((2 * round (_size / 2)) max 4) min 8;
	if ((count _pos) < 2 || {!((_pos select 0) isEqualType 0)} || {!((_pos select 1) isEqualType 0)}) exitWith {"posicion no valida"};
	_pos = [_pos select 0, _pos select 1, 0];
	if ((_pos select 0) < 0 || {(_pos select 1) < 0} || {(_pos select 0) > worldSize} || {(_pos select 1) > worldSize}) exitWith {"el objetivo esta fuera del mapa"};
	//--- fuera de tu base (HQ y estructuras) y lejos de las bases enemigas
	private _base = [_side] call VIOC_fnc_soBase;
	private _sts = _side call CTI_CO_FNC_GetSideStructures;
	if (isNil "_sts" || {!(_sts isEqualType [])}) then {_sts = []};
	if ((count _base > 0 && {(_base distance2D _pos) < VIOC_SO_PREQ_BASER}) || {({(_x isEqualType objNull) && {!isNull _x} && {(_x distance2D _pos) < VIOC_SO_PREQ_BASER}} count _sts) > 0}) exitWith {"el objetivo esta dentro de tu base: elige un pueblo o un punto fuera de ella"};
	if (({(_x distance2D _pos) < VIOC_SO_PREQ_ENEMYR} count ([_side] call VIOC_fnc_soEnemyBases)) > 0) exitWith {"el objetivo esta demasiado cerca de la base enemiga"};
	private _pkgs = [_side] call VIOC_fnc_soSidePackages;
	if (count _pkgs == 0) exitWith {"tu bando no tiene unidades especiales en este escenario"};
	//--- topes: soldados pedidos vivos del bando y presupuesto de IA
	private _mine = {alive _x && {_x getVariable ["vioc_so_preq", false]} && {!(_x getVariable ["vioc_so_exfil", false])} && {!(_x getVariable ["vioc_so_joined", false])} && {(side group _x) == _side}} count allUnits;
	if ((_mine + _size) > VIOC_SO_PREQ_SIDECAP) exitWith {format ["tu bando ya tiene %1 soldados especiales pedidos en el terreno (tope %2 con el nuevo equipo)", _mine, VIOC_SO_PREQ_SIDECAP]};
	if !([_size + 1] call VIOC_fnc_soPerfOk) exitWith {"ahora hay demasiada IA en la partida (presupuesto VIOC_PERF_AI_MAX); prueba mas tarde"};
	//--- objetivo: pueblo cercano al clic (propio = defender, otro = atacar) o el punto mismo
	private _sid = [_side] call VIOC_fnc_soSideID;
	private _town = objNull;
	private _bd = VIOC_SO_PREQ_TOWNR;
	{
		private _d = _x distance2D _pos;
		if (_d < _bd) then {_bd = _d; _town = _x};
	} forEach (missionNamespace getVariable ["CTI_Towns", []]);
	if (isNull _town && {surfaceIsWater _pos}) exitWith {"haz clic en tierra o cerca de un pueblo"};
	private _mode = "point";
	private _helper = objNull;
	if (isNull _town) then {
		//--- objeto invisible y solo local que hace de "pueblo" para las funciones de la operacion (se borra al terminar)
		_helper = "Land_ClutterCutter_small_F" createVehicleLocal _pos;
		_helper setPosATL _pos;
		_helper enableSimulation false;
		_helper setVariable ["cti_town_name", format ["la cuadricula %1", mapGridPosition _pos]];
		_town = _helper;
	} else {
		_mode = ["attack", "defend"] select ((_town getVariable ["cti_town_sideID", -1]) == _sid);
	};
	private _r = [_player, _side, _uid, _want, _town, _mode, _helper, _base, _pkgs, _join, _size, _seen, _cap] call VIOC_fnc_soPreqLaunch;
	if (_r != "ok" && {!isNull _helper}) then {deleteVehicle _helper};
	_r
};

//--- Elige paquete, tipo y lugar (VIOC_fnc_soPlan), cobra al jugador y lanza la operacion (VIOC_fnc_soRunOp).
VIOC_fnc_soPreqLaunch = {
	params ["_player", "_side", "_uid", "_want", "_town", "_mode", "_helper", "_base", "_pkgs", "_join", "_size", "_seen", "_cap"];
	if (_mode != "attack" && {_want == "raid"}) exitWith {"la incursion a pie solo va contra un pueblo que no es tuyo"};
	//--- desde donde: lo propio mas cercano al objetivo (pueblo propio o base); la zona de salto queda de ese lado
	private _tp = getPosATL _town;
	private _from = [];
	private _bf = 1e9;
	{
		private _d = _x distance2D _tp;
		if (_d > 300 && {_d < _bf}) then {_bf = _d; _from = _x};
	} forEach ([_side, _base] call VIOC_fnc_soAnchors);
	if (count _from == 0) then {_from = if (count _base > 0) then {_base} else {_tp getPos [1000, random 360]}};
	private _home = if (count _base > 0) then {_base} else {_from};
	private _plan = [_side, _town, _mode, _from, _want, _pkgs] call VIOC_fnc_soPlan;
	if (_plan isEqualType "") exitWith {
		if (_plan select [0, 11] == "sin opcione") exitWith {"ese tipo de operacion no esta disponible ahora (la incursion a pie es solo de noche)"};
		_plan
	};
	_plan params ["_pkg", "_type", "_main", "_dz", "_air"];
	private _unit = round ((call VIOC_fnc_soUnitPrice) * VIOC_SO_PREQ_MULT);
	private _price = round (([_size, _type] call VIOC_fnc_soPrice) * VIOC_SO_PREQ_MULT);
	if (_seen >= 0 && {_price > (_seen + 1)}) exitWith {format ["el precio cambio: ahora cuesta %1 (viste %2); vuelve a pedirla", _price, _seen]};
	//--- cobro (sin interrupciones entre mirar los fondos y descontarlos)
	private _grp = group _player;
	private _paid = false;
	private _funds = 0;
	isNil {
		_funds = [_grp, _side] call CTI_CO_FNC_GetFunds;
		if (isNil "_funds" || {!(_funds isEqualType 0)}) then {_funds = 0};
		if (_funds >= _price) then {
			[_grp, _side, -_price] call CTI_CO_FNC_ChangeFunds;
			_paid = true;
		};
	};
	if (!_paid) exitWith {format ["no te alcanza: cuesta %1 y tienes %2", _price, round _funds]};
	//--- paquete propio de este pedido: mismo contenido, nombre con "(pedida por ...)" y marca para sus soldados
	private _pk = createHashMap;
	{_pk set [_x, _pkg get _x]} forEach (keys _pkg);
	_pk set ["name", format ["%1 (pedida por %2)", _pkg get "name", name _player]];
	_pk set ["preq", true];
	private _tok = format ["preq_%1_%2", _uid, time];
	VIOC_SO_PREQ pushBack [_uid, _tok, time, _helper];
	[_uid, time] call VIOC_fnc_soPreqSetCD;
	private _srvCap = missionNamespace getVariable ["CTI_AI_PLAYER_TEAMS_GROUPSIZE", 12];
	if !(_srvCap isEqualType 0) then {_srvCap = 12};
	private _bonus = missionNamespace getVariable ["CTI_AI_PLAYERS_TEAMS_SOLDIER_GROUPSIZE", 6];
	if !(_bonus isEqualType 0) then {_bonus = 6};
	private _capEff = (_cap max _srvCap) min (_srvCap + _bonus);
	private _op = createHashMapFromArray [["side", _side], ["pkg", _pk], ["type", _type], ["town", _town], ["mode", _mode], ["from", _from], ["home", _home], ["pos", _dz], ["air", _air], ["chute", _pkg get "vchute"], ["size", _size], ["price", _price], ["unit", _unit], ["payer", ["player", _grp, _uid, _price, _side]], ["main", _main], ["tok", _tok], ["preq", _uid], ["join", _join], ["req", _player], ["cap", _capEff]];
	private _tname = _town getVariable ["cti_town_name", "?"];
	private _goal = if (_mode == "defend") then {format ["para defender %1", _tname]} else {format ["hacia %1", _tname]};
	[_side, format ["[Operacion especial] %1: %2 %3 (costo %4).", VIOC_SO_TYPENAMES getOrDefault [_type, _type], _pk get "name", _goal, _price]] call VIOC_fnc_soSay;
	private _after = if (_join) then {format ["Al llegar se uniran a tu grupo si caben (ahora %1/%2).", count units _grp, _capEff]} else {"Al llegar atacaran por su cuenta."};
	if (_mode == "point") then {_after = _after + " Sin pueblo cerca: aseguran la zona y se retiran a los 40 min."};
	[_player, true, format ["%1: %2, %3 soldados %4. Costo %5 (de tus fondos). %6", VIOC_SO_TYPENAMES getOrDefault [_type, _type], _pkg get "name", _size, _goal, _price, _after], VIOC_SO_PREQ_COOLDOWN] call VIOC_fnc_soPreqReply;
	format ["pedido de %1 (%2): %3 %4 %5 (%6) %7 soldados, costo %8, unirse %9", name _player, _side, _pkg get "id", _type, _tname, _mode, _size, _price, _join] call VIOC_fnc_soLog;
	[_op] spawn VIOC_fnc_soRunOp;
	"ok"
};

//--- Para los clientes: bandos con paquetes y datos para el precio estimado (una vez, cuando la mision esta lista).
[] spawn {
	waitUntil {sleep 2; !isNil "CTI_Init_Server" && {!isNil "CTI_InitTowns"}};
	VIOC_SO_PREQ_AVAIL = [west, east] apply {(VIOC_SO_PREQ_MODE > 0) && {count ([_x] call VIOC_fnc_soSidePackages) > 0}};
	VIOC_SO_PREQ_CFG = [call VIOC_fnc_soUnitPrice, VIOC_SO_PREQ_MULT, VIOC_SO_PREQ_COOLDOWN, VIOC_SO_PREQ_TOWNR, VIOC_SO_PREQ_BASER];
	publicVariable "VIOC_SO_PREQ_CFG";
	publicVariable "VIOC_SO_PREQ_AVAIL";
	format ["pedidos de jugadores: modo %1 (precio x%2, enfriamiento %3 min), oeste/este con paquetes %4", VIOC_SO_PREQ_MODE, VIOC_SO_PREQ_MULT, VIOC_SO_PREQ_COOLDOWN / 60, VIOC_SO_PREQ_AVAIL] call VIOC_fnc_soLog;
};

class VIOC_SPECOPS_PLAYER {
	title = "VIOC: Pedir operaciones especiales a la IA (accion PEDIR para cualquier jugador, pagadas con tus fondos)";
	values[] = {0,1,2};
	texts[] = {"No","Si","Si, a mitad de precio"};
	default = 1;
};
class VIOC_SPECOPS_PLAYER_COOLDOWN {
	title = "VIOC: Operaciones especiales pedidas, una como maximo cada (por jugador)";
	values[] = {5,10,15,20,30};
	texts[] = {"5 min","10 min","15 min","20 min","30 min"};
	default = 10;
};
